    @Test
    void freteGratisZeraDescontoIgualAoFrete() {
        ResumoRequest request = new ResumoRequest(
                List.of(new ItemRequest("Camiseta", new BigDecimal("79.90"), 1, new BigDecimal("0.30"))),
